<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();verify_csrf();if($_SERVER['REQUEST_METHOD']!=='POST')exit; $pid=(int)$_POST['product_id'];$rating=max(1,min(5,(int)$_POST['rating']));$body=trim($_POST['body']);if($body!==''){$st=$pdo->prepare("INSERT INTO reviews(user_id,product_id,rating,body,is_approved) VALUES(?,?,?,?,0)");$st->execute([$_SESSION['user']['id'],$pid,$rating,$body]);}header('Location: ../product.php?id='.$pid.'#reviews');exit;
